import { createRequire } from "node:module";
import { writeFile } from "node:fs/promises";

const unicodeVersion = "16.0.0";
const require = createRequire(import.meta.url);

const identifierStartRanges = loadRanges("ID_Start");
const identifierContinueRanges = loadRanges("ID_Continue");

const output = `// Generated by packages/core/scripts/generate-unicode-identifier-ranges.mjs.
// Unicode ${unicodeVersion}, Binary Properties ID_Start and ID_Continue.
// Do not edit this file directly.

${emitRangeMap("unicodeIdentifierStartRanges", identifierStartRanges)}

${emitRangeMap("unicodeIdentifierContinueRanges", identifierContinueRanges)}
`;

await writeFile(
  new URL("../src/unicode-identifier-ranges.generated.ts", import.meta.url),
  output,
);

function loadRanges(property) {
  const ranges = require(
    `@unicode/unicode-${unicodeVersion}/Binary_Property/${property}/ranges.js`,
  );

  validateRanges(property, ranges);
  return ranges;
}

function validateRanges(property, ranges) {
  let previousEnd = -1;

  for (const range of ranges) {
    if (!Number.isInteger(range.begin) || !Number.isInteger(range.end)) {
      throw new TypeError(`${property} contains a non-integer range boundary.`);
    }
    if (range.begin < 0 || range.begin >= range.end || range.end > 0x110000) {
      throw new RangeError(`${property} contains an invalid Unicode range.`);
    }
    if (range.begin < previousEnd) {
      throw new RangeError(`${property} ranges are not sorted and disjoint.`);
    }
    previousEnd = range.end;
  }
}

function emitRangeMap(name, ranges) {
  const entries = ranges.map(
    ({ begin, end }) => `${formatCodePoint(begin)}, ${formatCodePoint(end - 1)}`,
  );
  const lines = [];

  for (let index = 0; index < entries.length; index += 4) {
    lines.push(`  ${entries.slice(index, index + 4).join(", ")},`);
  }

  return `export const ${name}: readonly number[] = [\n${lines.join("\n")}\n];`;
}

function formatCodePoint(codePoint) {
  return `0x${codePoint.toString(16).toUpperCase()}`;
}
